<template>
  <main class="user-setup" aria-label="User Setup Story">
    <header class="setup-top"><span>User Setup</span><button class="usx-btn" :disabled="busy" @click="later">Do this later<UIcon name="close" /></button></header>
    <p v-if="error" class="setup-error" role="alert">{{ error }}</p>
    <p v-if="!loaded">Loading your setup…</p>
    <StoryWizard v-else :steps="steps" :model-value="step" :allow-jump="false" :busy="busy" :next-disabled="!canContinue" finish-label="Start my workspace" @update:model-value="move" @finish="finish">
      <template #step-0><div class="setup-question"><label for="setup-name">Your name</label><input id="setup-name" ref="nameInput" v-model="name" autocomplete="name" maxlength="100" required @keydown.enter.prevent="move(1)" /><p>This names your local profile. You can change it later.</p></div></template>
      <template #step-1><div class="setup-question"><label for="setup-city">City or region <small>optional</small></label><input id="setup-city" v-model="city" autocomplete="address-level2" maxlength="120" /><label for="setup-country">Country <small>optional</small></label><input id="setup-country" v-model="country" autocomplete="country-name" maxlength="120" /><p>Use a broad location. We do not request GPS access or upload your profile location.</p></div></template>
      <template #step-2><div class="setup-question"><label for="setup-zone">Device timezone</label><input id="setup-zone" :value="hostZone" readonly /><p>Your device manages the clock and timezone. uCore follows it automatically.</p><label for="setup-locale">Date and time format</label><select id="setup-locale" v-model="locale"><option v-for="option in localeOptions" :key="option.id" :value="option.id">{{ option.name }}</option></select><output>{{ sampleDate }}</output></div></template>
      <template #step-3><div class="setup-question"><label for="setup-theme">Appearance</label><select id="setup-theme" v-model="theme"><option value="auto">Follow my device</option><option value="dark">Dark</option><option value="light">Light</option></select><label for="setup-font">Text size</label><input id="setup-font" v-model.number="fontSize" type="number" min="12" max="24" /><p :style="{fontSize:fontSize+'px'}">Your knowledge, tasks and notes in one calm workspace.</p></div></template>
      <template #step-4><div class="setup-question"><fieldset><legend>Start here when setup finishes</legend><label v-for="option in startOptions" :key="option.id" class="setup-choice"><input type="radio" v-model="startSurface" :value="option.id" /><UIcon :name="option.icon" /><span>{{ option.label }}<small>{{ option.description }}</small></span></label></fieldset><p>Your documents stay in your existing Vault. Connections use only the lists and groups you choose.</p></div></template>
      <template #step-5><div class="setup-accounts"><p>Apple uses local macOS permissions. Google uses OAuth in your system browser. Both are optional; you can connect later.</p><ConnectionsPanel connections-only /></div></template>
      <template #step-6><div class="setup-question"><dl class="setup-review"><dt>Name</dt><dd>{{ name }}</dd><dt>Location</dt><dd>{{ [city,country].filter(Boolean).join(', ') || 'Not set' }}</dd><dt>Timezone</dt><dd>{{ hostZone }} · follows device</dd><dt>Date format</dt><dd>{{ locale }}</dd><dt>Appearance</dt><dd>{{ theme }} · {{ fontSize }}px</dd><dt>Start with</dt><dd>{{ startOptions.find(option=>option.id===startSurface)?.label }}</dd></dl><p>Your profile stays local. Only enabled connections sync the source lists and records you selected. Duplicate suggestions and competing changes remain available for review.</p></div></template>
      <template #footer-center><span class="setup-save-note">{{ busy ? 'Saving…' : 'Progress is saved when you continue' }}</span></template>
    </StoryWizard>
  </main>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import StoryWizard from '../../skills/organisms/StoryWizard.vue';
import ConnectionsPanel from './ConnectionsPanel.vue';
import UIcon from '../../skills/atoms/UIcon.vue';
import { useIdentityStore } from '../../stores/identity';
import { useSettingsStore } from '../../stores/settings';
import { UCORE_BASE } from '../../api/base';
const router=useRouter(), identity=useIdentityStore(), preferences=useSettingsStore();
const step=ref(0), loaded=ref(false), busy=ref(false), error=ref(''), nameInput=ref<HTMLInputElement|null>(null);
const name=ref(''),city=ref(''),country=ref(''),locale=ref(navigator.language||'en-AU');
const hostZone=Intl.DateTimeFormat().resolvedOptions().timeZone;
const theme=ref<'auto'|'dark'|'light'>('auto'),fontSize=ref(16),startSurface=ref('workflow');
const steps=[{title:'What should we call you?',subtitle:'Let’s make this workspace yours.'},{title:'Where are you based?',subtitle:'A broad location is enough.'},{title:'Make time feel familiar',subtitle:'Your device remains the clock authority.'},{title:'Make it comfortable',subtitle:'Choose a clear, readable display.'},{title:'What would you like to do first?',subtitle:'Everything else stays one tab away.'},{title:'Connect the accounts you choose',subtitle:'Choose collections, then lists or groups. Start with pull-only if you prefer.'},{title:'Ready to begin?',subtitle:'Review your choices before saving your profile.'}];
const localeOptions=computed(()=>[...new Map([{id:navigator.language||'en-AU',name:'Device format ('+(navigator.language||'en-AU')+')'},{id:'en-AU',name:'English · Australia'},{id:'en-GB',name:'English · United Kingdom'},{id:'en-US',name:'English · United States'},{id:'de-DE',name:'Deutsch'},{id:'fr-FR',name:'Français'},{id:'es-ES',name:'Español'}].map(option=>[option.id,option])).values()]);
const sampleDate=computed(()=>{try{return new Intl.DateTimeFormat(locale.value,{dateStyle:'full',timeStyle:'short'}).format(new Date());}catch{return new Intl.DateTimeFormat(undefined,{dateStyle:'full',timeStyle:'short'}).format(new Date());}});
const startOptions=[{id:'workflow',label:'My daily workflow',icon:'checklist',description:'Tasks, contacts, notes and monitored feeds'},{id:'knowledge',label:'My knowledge library',icon:'auto_stories',description:'Read and curate local knowledge'},{id:'ucode',label:'uCode',icon:'terminal',description:'Simple commands and learning'},{id:'research',label:'Research',icon:'travel_explore',description:'Collect findings and connect them to work'}];
const startPaths:Record<string,string>={workflow:'/workflow',knowledge:'/documentation?tab=wiki',ucode:'/ucode',research:'/workflow?tab=research'};
const canContinue=computed(()=>!!name.value.trim() && fontSize.value>=12 && fontSize.value<=24 && !!hostZone);
function answers(){return {city:city.value,country:country.value,locale:locale.value,host_timezone:hostZone,start_surface:startSurface.value,theme_mode:theme.value,font_size:String(fontSize.value)};}
async function request(path:string,body?:any){const response=await fetch(`${UCORE_BASE}/api/connections${path}`,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!response.ok)throw Error((await response.text()).slice(0,240));return response.json();}
async function save(next:number,completed=false,deferred=false){await request('/setup',{display_name:name.value,answers:answers(),step:next,completed,deferred});}
async function focusQuestion(){await nextTick();document.querySelector<HTMLElement>('.user-setup .story-wizard__slide input:not([readonly]),.user-setup .story-wizard__slide select')?.focus();}
async function move(next:number){if(busy.value || (next>step.value&&!canContinue.value))return;busy.value=true;error.value='';try{await save(next);step.value=next;await focusQuestion();}catch(exc){error.value=exc instanceof Error?exc.message:'Setup could not be saved';}finally{busy.value=false;}}
async function later(){if(busy.value)return;busy.value=true;try{await save(step.value,false,true);await router.push('/');}catch(exc){error.value=exc instanceof Error?exc.message:'Setup could not be paused';}finally{busy.value=false;}}
async function finish(){if(!canContinue.value||busy.value)return;busy.value=true;error.value='';try{preferences.setThemeMode(theme.value);preferences.setFontSize(fontSize.value);await preferences.save();if(preferences.syncError)throw Error(preferences.syncError);await save(6,true);await identity.load();await router.replace(startPaths[startSurface.value]||'/workflow');}catch(exc){error.value=exc instanceof Error?exc.message:'Setup could not be completed';}finally{busy.value=false;}}
onMounted(async()=>{try{await identity.load();const state=await request('');const responses=state.setup_story?.responses||{};const profile=state.user_profile||{};name.value=responses.display_name||state.setup.display_name||identity.displayName;city.value=responses.city||profile.city||'';country.value=responses.country||profile.country||'';locale.value=responses.locale||profile.locale||navigator.language||'en-AU';theme.value=responses.theme_mode||preferences.themeMode;fontSize.value=Number(responses.font_size||preferences.fontSize);startSurface.value=responses.start_surface||profile.start_surface||'workflow';step.value=Math.min(6,Math.max(0,Number(state.setup.step||0)));loaded.value=true;await focusQuestion();}catch(exc){error.value=exc instanceof Error?exc.message:'Setup is unavailable';}});
</script>
<style scoped>
.user-setup { height:100dvh;display:flex;flex-direction:column;box-sizing:border-box;background:var(--usx-color-background);color:var(--usx-color-on-surface);font-family:var(--usx-font-family-sans); }
.setup-top {display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 16px;flex-shrink:0;font-size:var(--usx-font-size-sm);}.setup-top .usx-btn{display:inline-flex;align-items:center;gap:6px;min-height:32px;margin:0;padding:0 8px;border:0;background:transparent;box-shadow:none;}.setup-top :deep(.u-icon){font-size:20px;}
.user-setup :deep(.story-wizard){width:min(100%,68rem);margin-inline:auto;min-height:0;flex:1;}.user-setup :deep(.story-wizard__header){border:0;padding:24px 24px 8px;}.user-setup :deep(.story-wizard__title){font-size:clamp(1.6rem,4vw,2.5rem);line-height:1.25;}.user-setup :deep(.story-wizard__dots){padding:8px 24px;margin:0;}.user-setup :deep(.story-wizard__stage){min-height:0;flex:1;overflow-y:auto;padding:16px 24px;}.user-setup :deep(.story-wizard__slide){position:relative;inset:auto;min-height:0;padding:0;margin:0;}.user-setup :deep(.story-wizard__nav){flex-shrink:0;padding:12px 24px;border-top:1px solid var(--usx-color-border);}.setup-question{display:grid;gap:12px;width:min(100%,40rem);margin:0 auto;}.setup-question label{margin:0;font-size:var(--usx-font-size-base);}.setup-question p,.setup-accounts>p{color:var(--usx-color-on-surface-muted);font-size:var(--usx-font-size-sm);line-height:1.6;margin:0;}.setup-question input:not([type=radio]),.setup-question select{box-sizing:border-box;width:100%;height:44px;min-height:44px;padding:8px 12px;margin:0;border:1px solid var(--usx-color-border);border-radius:var(--usx-radius-sm);background:var(--usx-color-surface);color:inherit;font:inherit;box-shadow:none;outline:0;}.setup-question input:focus-visible,.setup-question select:focus-visible{outline:2px solid var(--usx-color-primary);outline-offset:-2px;border-color:transparent;}.setup-question fieldset{display:grid;gap:8px;padding:0;border:0;margin:0;}.setup-choice{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--usx-color-border);border-radius:var(--usx-radius-sm);}.setup-choice small{display:block;color:var(--usx-color-on-surface-muted);font-size:var(--usx-font-size-sm);}.setup-choice input{margin:0;}.setup-review{display:grid;grid-template-columns:auto minmax(0,1fr);gap:10px;margin:0;}.setup-review dd{margin:0;overflow-wrap:anywhere;}.setup-review dt{color:var(--usx-color-on-surface-muted);}.setup-save-note{font-size:var(--usx-font-size-xs);color:var(--usx-color-on-surface-muted);}.setup-error{margin:8px 24px;color:var(--usx-color-danger);}.setup-accounts :deep(.connections){padding:12px 0;}.setup-accounts{width:100%;}
@media(max-width:40rem){.setup-save-note{display:none;}.user-setup :deep(.story-wizard__header),.user-setup :deep(.story-wizard__stage){padding-inline:16px;}.user-setup :deep(.story-wizard__nav){padding:8px 16px;}}
</style>
